<?php
require __DIR__.'/config.php';$me=require_auth();$s=db()->prepare("SELECT a.account_id,a.account_number,a.account_title FROM account_holders h JOIN accounts a ON a.account_id=h.account_id WHERE h.customer_id=? ORDER BY a.account_id DESC");$s->execute([$me['customer_id']]);$accounts=$s->fetchAll();$ids=array_map('intval',array_column($accounts,'account_id'));$types=['deposit','withdrawal','transfer_in','transfer_out','fee','interest'];$filters=['account_id'=>trim((string)($_GET['account_id']??'')),'type'=>trim((string)($_GET['type']??'')),'from'=>trim((string)($_GET['from']??'')),'to'=>trim((string)($_GET['to']??'')),'q'=>trim((string)($_GET['q']??''))];$page=max(1,(int)($_GET['page']??1));$perPage=20;$error='';
if($filters['account_id']!==''&&(!ctype_digit($filters['account_id'])||!in_array((int)$filters['account_id'],$ids,true))){$error='The selected account could not be found.';$filters['account_id']='';}
if($filters['type']!==''&&!in_array($filters['type'],$types,true)){$error='The selected transaction type is invalid.';$filters['type']='';}
foreach(['from','to'] as $key){if($filters[$key]!==''){$date=DateTimeImmutable::createFromFormat('!Y-m-d',$filters[$key]);if(!$date||$date->format('Y-m-d')!==$filters[$key]){$error='Enter a valid date in YYYY-MM-DD format.';$filters[$key]='';}}}
if($filters['from']&&$filters['to']&&$filters['from']>$filters['to']){$error='The start date must be on or before the end date.';$filters['from']=$filters['to']='';}
$where=[];$params=[];if(!$ids){$where[]='1=0';}else{$where[]='t.account_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';array_push($params,...$ids);}if($filters['account_id']!==''){$where[]='t.account_id=?';$params[]=(int)$filters['account_id'];}if($filters['type']!==''){$where[]='t.transaction_type=?';$params[]=$filters['type'];}if($filters['from']!==''){$where[]='t.created_at>=?';$params[]=$filters['from'].' 00:00:00';}if($filters['to']!==''){$where[]='t.created_at<?';$params[]=(new DateTimeImmutable($filters['to']))->modify('+1 day')->format('Y-m-d').' 00:00:00';}if($filters['q']!==''){$where[]='(t.reference_number LIKE ? OR t.description LIKE ?)';$params[]='%'.$filters['q'].'%';$params[]='%'.$filters['q'].'%';}$clause=implode(' AND ',$where);
$s=db()->prepare("SELECT COUNT(*) FROM transactions t WHERE $clause");$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$s=db()->prepare("SELECT t.transaction_id,t.reference_number,t.account_id,t.transaction_type,t.amount,t.balance_after,t.description,t.status,t.created_at,a.account_number FROM transactions t JOIN accounts a ON a.account_id=t.account_id WHERE $clause ORDER BY t.created_at DESC,t.transaction_id DESC LIMIT $perPage OFFSET $offset");$s->execute($params);$rows=$s->fetchAll();$query=$filters;render_start('Activity & statements');?><section class="page-heading"><div class="eyebrow dark">Your account history</div><h1>Activity &amp; statements</h1><p>Search, filter, review, and print transaction records for your accounts.</p></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><form class="filter-card" method="get"><div class="filter-grid"><div class="field"><label for="account_id">Account</label><select name="account_id" id="account_id"><option value="">All my accounts</option><?php foreach($accounts as $a):?><option value="<?=$a['account_id']?>" <?=(string)$a['account_id']===$filters['account_id']?'selected':''?>><?=e($a['account_title'])?> · •••• <?=e(substr($a['account_number'],-4))?></option><?php endforeach;?></select></div><div class="field"><label for="type">Transaction type</label><select name="type" id="type"><option value="">All types</option><?php foreach($types as $t):?><option value="<?=e($t)?>" <?=$filters['type']===$t?'selected':''?>><?=e(ucwords(str_replace('_',' ',$t)))?></option><?php endforeach;?></select></div><div class="field"><label for="from">From date</label><input type="date" id="from" name="from" value="<?=e($filters['from'])?>"></div><div class="field"><label for="to">To date</label><input type="date" id="to" name="to" value="<?=e($filters['to'])?>"></div><div class="field filter-search"><label for="q">Search reference or description</label><input id="q" name="q" value="<?=e($filters['q'])?>" maxlength="100"></div><div class="filter-actions"><button class="button navy" type="submit">Apply filters</button> <a class="button pale" href="<?=e(url('activity.php'))?>">Clear</a></div></div></form><div class="section-heading"><h2>Transactions</h2><span class="muted"><?=number_format($total)?> result<?=($total===1?'':'s')?></span></div><?php if($rows):?><div class="table-wrap"><table><thead><tr><th>Date &amp; time</th><th>Account</th><th>Reference</th><th>Type</th><th>Status</th><th>Amount</th><th>Balance after</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td>•••• <?=e(substr($r['account_number'],-4))?></td><td><?=e($r['reference_number'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['transaction_type'])))?></td><td><?=e(ucfirst($r['status']))?></td><td>BDT <?=e(number_format((float)$r['amount'],2))?></td><td>BDT <?=e(number_format((float)$r['balance_after'],2))?></td><td><a href="<?=e(url('transaction.php?id='.(int)$r['transaction_id']))?>">View slip</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No transactions match these filters.</div><?php endif;?><?php if($pages>1):?><nav class="pagination" aria-label="Statement pages"><?php if($page>1):$query['page']=$page-1;?><a href="<?=e(url('activity.php?'.http_build_query($query)))?>">← Previous</a><?php endif;?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages):$query['page']=$page+1;?><a href="<?=e(url('activity.php?'.http_build_query($query)))?>">Next →</a><?php endif;?></nav><?php endif;?><?php render_end();?>
